import React from 'react';
import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect, waitFor } from 'storybook/test';
import { Button } from '@leafygreen-ui/button';
import Popconfirm from '.';

const meta = {
  component: Popconfirm,
  tags: ['ai-generated'],
} satisfies Meta<typeof Popconfirm>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  render: () => (
    <Popconfirm trigger={<Button>Delete Item</Button>}>
      Are you sure you want to delete this item?
    </Popconfirm>
  ),
  play: async ({ canvas, userEvent }) => {
    const trigger = canvas.getByRole('button', { name: /delete item/i });
    await expect(trigger).toBeVisible();
    await userEvent.click(trigger);
    await waitFor(() => {
      expect(canvas.getByText('Are you sure you want to delete this item?')).toBeVisible();
    });
  },
};

export const WithCustomConfirmText: Story = {
  render: () => (
    <Popconfirm
      confirmText="Confirm Delete"
      trigger={<Button>Remove</Button>}
    >
      This action cannot be undone.
    </Popconfirm>
  ),
  play: async ({ canvas, userEvent }) => {
    const trigger = canvas.getByRole('button', { name: /remove/i });
    await userEvent.click(trigger);
    await waitFor(() => {
      expect(canvas.getByRole('button', { name: /confirm delete/i })).toBeVisible();
    });
  },
};

export const ConfirmDisabled: Story = {
  render: () => (
    <Popconfirm
      confirmDisabled
      trigger={<Button>Action</Button>}
    >
      Cannot confirm right now.
    </Popconfirm>
  ),
  play: async ({ canvas, userEvent }) => {
    const trigger = canvas.getByRole('button', { name: /action/i });
    await userEvent.click(trigger);
    await waitFor(() => {
      const confirmBtn = canvas.getByRole('button', { name: /yes/i });
      expect(confirmBtn).toBeDisabled();
    });
  },
};

